		System.out.println("Hello, World!");
		 
		
		// variables 
		int age = 25;
		double price = 19.99;
		String name = "John";
		
		
		// conditionals


		
		
		
		int xs = 10;
		if (xs > 5) {
		    System.out.println("x is greater than 5");
		} else {
		    System.out.println("x is not greater than 5");
		}
		
		
		// Loops
		int[] numbers = {1, 2, 3, 4, 5};
